import urllib.request,pathlib
p=pathlib.Path('/tmp/georutter-segunda/es')
urls=[('edist','https://www.edistribucion.com/content/dam/edistribucion/conexion-a-la-red/descargables/nodos/generacion/202611/2026_11_04_R1299_generaci%C3%B3n.csv'),('ufd','https://www.ufd.es/wp-content/uploads/2026/11/2026_11_01_R1-002_demanda.csv'),('ree','https://www.ree.es/sites/default/files/12_CLIENTES/Documentos/2026_11_03_GRT_generacion.csv'),('cnig','https://centrodedescargas.cnig.es/CentroDescargas/detalleArchivo?sec=12165674')]
for name,u in urls:
 try:
  r=urllib.request.urlopen(u,timeout=30);b=r.read(100000000);(p/(name+'.data')).write_bytes(b);print(name,r.status,r.headers.get('Content-Type'),len(b),b[:100])
 except Exception as e:print(name,repr(e))
